async function renderContent(code,token){
  const cur=CURATED[code],g=GUIDE[code],name=nm(code),enName=enBase(code).replace(/\s*\(.*\)/,"");
  $("#bannerEyebrow").textContent=t("guide");$("#bannerTitle").textContent=name;$("#bannerNumber").textContent=pad(INDEX_OF[code]+1,3);
  $("#challengeCountryName").textContent=name;$("#challengeCountryLabel").textContent=`${name.toUpperCase()} · ${pad(INDEX_OF[code]+1)}`;
  $("#guideCountry").innerHTML=`${flagImg(code,"lg")} ${esc(name)}`;
  S.desc=cur&&lang==="en"?cur.desc:"";$("#bannerDescription").textContent=S.desc;
  S.places=[];S.facts=null;S.voyage=null;setPins([]);
  $("#countryFacts").innerHTML="";
  if(cur){
    setPlaces(cur.places.map((p,i)=>({title:p[0],tag:p[1],text:p[2],wiki:g.wiki[i]})),enName);
    $("#foodBlock").hidden=false;$("#foodGrid").innerHTML=cur.food.map(f=>foodCard({emoji:f[0],title:f[1],text:f[2]})).join("");
    wikiThumbs([...g.wiki,g.cover],1600).then(m=>{if(token!==renderToken)return;const c=m.get(g.cover);if(c&&c.url)setBackdrops(c.url);else searchImage(g.cover+" "+enName,1600).then(u=>{if(u&&token===renderToken)setBackdrops(u)});
      const pins=g.wiki.map((w,i)=>{const r=m.get(w);return r&&r.lat!=null?{title:cur.places[i][0],lat:r.lat,lng:r.lng,idx:i}:null}).filter(Boolean);S.places.forEach((p,i)=>{const r=m.get(g.wiki[i]);if(r&&r.lat!=null){p.lat=r.lat;p.lng=r.lng}});setPins(pins)});
  }else{
    $("#destinationGrid").innerHTML=skeletons(6);$("#placeCount").textContent="…";$("#foodBlock").hidden=false;$("#foodGrid").innerHTML=skeletons(4);
    getAttractions(code).then(list=>{if(token!==renderToken)return;
      if(!list.length){setPlaces(mapsFallback(name),enName);return}
      setPlaces(list.map(p=>({...p,tag:t("worthSeeing")})),enName);
      setPins(list.filter(p=>p.lat!=null).map((p,i)=>({title:p.title,lat:p.lat,lng:p.lng,idx:i})));
      wikiThumbs([list[0].title],1600).then(m=>{const r=m.get(list[0].title);if(token===renderToken)setBackdrops(r&&r.url?r.url:list[0].img)})
    }).catch(()=>{if(token===renderToken)setPlaces(mapsFallback(name),enName)});
    getFood(code).then(list=>{if(token!==renderToken)return;if(list.length){$("#foodGrid").innerHTML=list.map(foodCard).join("")}else $("#foodBlock").hidden=true}).catch(()=>{if(token===renderToken)$("#foodBlock").hidden=true});
  }
  renderSelected();
  getDesc(code).then(d=>{if(token!==renderToken)return;S.desc=d;$("#bannerDescription").textContent=d;const sd=$("#selDesc");if(sd)sd.textContent=d});
  getFacts(code).then(d=>{if(token!==renderToken)return;S.facts=d;renderFacts(d);paintGuide();if(d&&d.latlng){S.latlng[code]=d.latlng;if(!featByCode[code]&&globe)flyTo(code)}}).catch(()=>{});
  getVoyage(code).then(v=>{if(token!==renderToken)return;S.voyage=v;paintGuide()}).catch(()=>{});
  initGuide(code);
}
