function postCard(p,st){
  const liked=!!st.liked[p.id],saved=!!st.saved[p.id],cm=st.comments[p.id]||[];
  const img=p.photo?`<img class="post-image" src="${p.photo}" alt="${esc(p.caption||"")}" loading="lazy" data-lightbox data-id="${p.id}">`:`<img class="post-image" data-wiki="${esc(p.wiki)}" data-wsize="900" alt="${esc(p.caption||"")}" loading="lazy" data-lightbox data-id="${p.id}">`;
  return `<article class="post-card" data-post="${p.id}"><header class="post-head"><span class="avatar">${esc(p.user[0].toUpperCase())}</span><div><b>@${esc(p.user)}</b><small>${p.cc?flagImg(p.cc)+" ":"⌖ "}${esc(p.location||"—")}</small></div><span class="post-age">${esc(p.age||t("justNow"))}</span></header>
  <div class="post-media">${img}<span class="heart-pop" aria-hidden="true">♥</span>${p.mine?"":`<span class="sample-badge">${t("sample")}</span>`}</div>
  <div class="post-meta"><div class="post-actions"><button type="button" class="${liked?"liked":""}" data-like="${p.id}" aria-pressed="${liked}" aria-label="Like">${liked?"♥":"♡"} <span>${(p.likes||0)+(liked?1:0)}</span></button><button type="button" data-cm="${p.id}" aria-label="${esc(t("commentsWord"))}">💬 <span>${cm.length}</span></button>${p.cc?`<button type="button" data-visit="${p.cc}">↗ ${t("exploreCountry")}</button>`:""}<button type="button" class="${saved?"on":""} spacer" data-save="${p.id}" aria-pressed="${saved}" aria-label="${esc(t("save"))}">${saved?"★":"☆"}</button>${p.mine?`<button type="button" class="danger" data-del="${p.id}">${t("del")}</button>`:""}</div>
  <p class="post-caption"><b>@${esc(p.user)}</b> ${hashTags(p.caption||"")}</p>
  <div class="comments" id="cm-${p.id}" hidden><ul>${cm.map(c=>`<li><b>@you</b> ${esc(c)}</li>`).join("")}</ul><form data-cmform="${p.id}"><input maxlength="160" placeholder="${esc(t("commentPh"))}" aria-label="${esc(t("commentPh"))}"><button type="submit">${t("send")}</button></form></div></div></article>`}
function toggleState(kind,id){const st=postState();st[kind][id]=!st[kind][id];if(!st[kind][id])delete st[kind][id];store.set("discoverPostState",st);renderFeed()}
