/* photo compression (shared with the book) */
function compress(file,max=1200,q=.8){return new Promise((res,rej)=>{const url=URL.createObjectURL(file),img=new Image();img.onload=()=>{let w=img.naturalWidth,h=img.naturalHeight;const k=Math.min(1,max/Math.max(w,h));w=Math.round(w*k);h=Math.round(h*k);const c=document.createElement("canvas");c.width=w;c.height=h;c.getContext("2d").drawImage(img,0,0,w,h);URL.revokeObjectURL(url);res(c.toDataURL("image/jpeg",q))};img.onerror=()=>{URL.revokeObjectURL(url);rej(new Error("img"))};img.src=url})}
/* ================= DISCOVER v3 — challenge + 3D page-turning travel book ================= */
function resetChallengeForm(){memoryData="";$("#memoryPhoto").value="";$("#memoryPhotoName").textContent=t("noPhoto");$("#memoryNote").value=""}
function renderTasks(){
  const all=store.get("discoverTasks",{});taskState=all[S.code]||[false,false,false,false];
  const cur=CURATED[S.code],places=cur?.places||[],foods=cur?.food||[];
  let labels=[t("task1"),t("task2"),t("task3"),t("task4")];
  if(lang==="en"){
    if(places[0])labels[0]=`Visit or research ${places[0][0]}`;
    if(foods[0])labels[1]=`Try or learn about ${foods[0][1]}`;
    labels[2]=`Learn a useful phrase in ${nm(S.code)}`;
    labels[3]=`Discover one local custom or cultural story`;
  }
  $("#challengeTasks").innerHTML=labels.map((label,i)=>`<label class="task"><input type="checkbox" data-task="${i}" ${taskState[i]?"checked":""}><span>${esc(label)}</span></label>`).join("");updateChallenge()
}
$("#challengeTasks").addEventListener("change",e=>{const i=e.target.closest("input[data-task]");if(!i)return;taskState[+i.dataset.task]=i.checked;const all=store.get("discoverTasks",{});all[S.code]=taskState;store.set("discoverTasks",all);updateChallenge()});
function updateChallenge(){const done=taskState.filter(Boolean).length;$("#challengePercent").textContent=Math.round(done/4*100)+"%";$("#completeCountryBtn").disabled=done!==4||!memoryData}
function updateProgress(){const n=getBook().length;$("#progressText").textContent=`${n} / ${COUNTRY_LIST.length} ${t("countries")}`;$("#progressBar").style.width=Math.min(100,n/COUNTRY_LIST.length*100)+"%"}
$("#memoryPhoto").addEventListener("change",async e=>{const f=e.target.files[0];if(!f)return;try{memoryData=await compress(f);$("#memoryPhotoName").textContent=f.name}catch(err){memoryData="";e.target.value="";toast(t("photoError"))}updateChallenge()});
$("#completeCountryBtn").addEventListener("click",()=>{const book=getBook();if(book.some(x=>x.code===S.code)){toast(t("inBook"));return}
  book.push({code:S.code,name:BY_CODE[S.code].en,photo:memoryData,note:$("#memoryNote").value.trim(),date:new Date().toLocaleDateString(lang),ts:Date.now()});
  if(!store.set("discoverBook",book)){toast(t("storageFull"));return}
  const all=store.get("discoverTasks",{});delete all[S.code];store.set("discoverTasks",all);
  resetChallengeForm();renderTasks();toast(t("bookAdded"));confetti();
  BK.k=0;renderBook();updateProgress();paintGlobe();
  setTimeout(()=>{$("#bookShell").scrollIntoView({behavior:"smooth",block:"center"});setTimeout(()=>goToSpread(spreadTarget(book.length-1)),700)},500)});
function confetti(){if(reduced())return;const c=$("#confetti"),x=c.getContext("2d");c.width=innerWidth;c.height=innerHeight;const cols=["#d9b47b","#86cbb8","#f4f0e8","#e07a5f"];const ps=Array.from({length:120},()=>({x:innerWidth/2,y:innerHeight*.6,vx:(Math.random()-.5)*14,vy:-Math.random()*15-4,s:4+Math.random()*5,c:cols[Math.random()*4|0],r:Math.random()*6,vr:(Math.random()-.5)*.4}));let f=0;(function step(){x.clearRect(0,0,c.width,c.height);ps.forEach(p=>{p.vy+=.35;p.x+=p.vx;p.y+=p.vy;p.r+=p.vr;x.save();x.translate(p.x,p.y);x.rotate(p.r);x.fillStyle=p.c;x.fillRect(-p.s/2,-p.s/2,p.s,p.s*.6);x.restore()});if(++f<130)requestAnimationFrame(step);else x.clearRect(0,0,c.width,c.height)})()}

/* ---------- the book ---------- */
const BK={k:0,L:0,busy:false,pages:0,single:false};
const mqBook=matchMedia("(max-width:700px)");
const spreadTarget=j=>BK.single?3+2*j:j+2;
function buildPages(){
  const book=getBook(),n=book.length,P=[];
  const total=COUNTRY_LIST.length;
  const tasks=Object.values(store.get("discoverTasks",{})).reduce((a,arr)=>a+arr.filter(Boolean).length,0)+n*4;
  const notes=book.filter(b=>b.note).length;
  // 0 front cover
  P.push(`<div class="pg cover"><div class="bc-top">THE COLLECTOR'S EDITION</div><div class="bc-emblem">✦</div><div class="bc-title">MY<br><i>TRAVEL</i><br>BOOK</div><div class="bc-bot">PLACES · PEOPLE · MEMORIES</div><div class="bc-hint">${t("tapToOpen")} →</div></div>`);
  // 1 welcome (left)
  P.push(`<div class="pg left welcome"><span class="pg-kick">${t("welcomeKick")}</span><h4>${t("welcomeTitle")}</h4><p>${t("welcomeText")}</p><div class="pg-ring" style="--p:${Math.max(2,n/total*100)}"><b>${n}</b><small>/ ${total}</small></div></div>`);
  // 2 contents (right)
  P.push(`<div class="pg right contents"><span class="pg-kick">${t("contents")}</span>${n?`<ol>${book.map((b,i)=>`<li><button type="button" data-entry="${i}">${flagImg(b.code)}<span>${esc(nm(b.code))}</span><i></i><em>${3+2*i}</em></button></li>`).join("")}</ol>`:`<p class="pg-empty">${t("emptyBook")}</p><button type="button" class="pg-btn" data-start>${t("startJourney")} →</button>`}<span class="pg-num">2</span></div>`);
  // entries
  book.forEach((b,i)=>{
    P.push(`<div class="pg left photo"><div class="polaroid"><img src="${b.photo}" alt=""><span class="tape"></span><span class="tape t2"></span></div><div class="pg-cap">${flagImg(b.code)} ${esc(nm(b.code))}</div><span class="pg-num">${3+2*i}</span></div>`);
    P.push(`<div class="pg right note"><span class="pg-kick">${esc(b.date||"")}</span><h4>${esc(nm(b.code))}</h4><p class="hand">${b.note?esc(b.note):"✦"}</p><div class="stamp">${t("visitedWord")}<small>${esc(b.date||"")}</small></div><button type="button" class="pg-btn" data-open="${b.code}">${t("openGuide")} →</button><span class="pg-num">${4+2*i}</span></div>`);
  });
  // wishlist (left) + passport (right)
  P.push(`<div class="pg left wishpg"><span class="pg-kick">${t("wishlistPage")}</span>${wish.length?`<div class="wish-list">${wish.slice(0,14).map(c=>`<button type="button" data-open="${c}">${flagImg(c)}<span>${esc(nm(c))}</span></button>`).join("")}</div>`:`<p class="pg-empty">${t("wishlistEmpty")}</p>`}<span class="pg-num">${3+2*n}</span></div>`);
  P.push(`<div class="pg right passport"><span class="pg-kick">${t("passportStats")}</span><div class="stat-grid"><div><b>${n}</b><small>${t("statCountries")}</small></div><div><b>${(n/total*100).toFixed(1)}%</b><small>${t("statWorld")}</small></div><div><b>${notes}</b><small>${t("statNotes")}</small></div><div><b>${tasks}</b><small>${t("statTasks")}</small></div></div><div class="stamps">${book.slice(0,12).map(b=>`<span>${flagImg(b.code)}</span>`).join("")}</div><p class="pg-end">${t("theEnd")} ✦</p><span class="pg-num">${4+2*n}</span></div>`);
  // back cover
  P.push(`<div class="pg cover back"><div class="bc-emblem">✦</div><div class="bc-bot">DISCOVER · ${new Date().getFullYear()}</div></div>`);
  return P;
}
function renderBook(keep){
  const single=mqBook.matches;if(single!==BK.single){BK.single=single;BK.k=0}
  const P=buildPages();BK.pages=P.length;BK.L=single?P.length:P.length/2;BK.k=Math.min(BK.k,BK.L);
  $("#book3d").innerHTML=single?P.map((p,i)=>`<div class="leaf single" data-i="${i}"><div class="face front">${p}</div></div>`).join(""):Array.from({length:BK.L},(_,i)=>`<div class="leaf" data-i="${i}"><div class="face front">${P[2*i]}</div><div class="face back">${P[2*i+1]}</div></div>`).join("");
  layoutBook();updateProgress();paintGlobe();
}
function layoutBook(){
  $$("#book3d .leaf").forEach((lf,i)=>{const fl=i<BK.k;lf.classList.toggle("flipped",fl);lf.style.zIndex=fl?i+1:BK.L-i});
  setBookState();
}
function setBookState(){
  const bk=$("#book3d");
  if(BK.single){bk.dataset.state="single";$("#pageInd").textContent=BK.k===0?t("cover"):`${BK.k} / ${BK.pages-2}`;$("#bookPrev").disabled=BK.k===0;$("#bookNext").disabled=BK.k>=BK.L-1;return}
  bk.dataset.state=BK.k===0?"closed":(BK.k===BK.L?"end":"open");
  $("#pageInd").textContent=BK.k===0?t("cover"):(BK.k===BK.L?"—":`${2*BK.k-1}–${2*BK.k} / ${BK.pages-2}`);
  $("#bookPrev").disabled=BK.k===0;$("#bookNext").disabled=BK.k===BK.L;
}
function turn(dir){
  if(BK.busy)return;const target=BK.k+dir;if(target<0||target>BK.L)return;
  if(BK.single&&target>BK.L-1){return}
  BK.busy=true;const idx=dir>0?BK.k:BK.k-1,lf=$(`#book3d .leaf[data-i="${idx}"]`);if(!lf){BK.busy=false;return}
  lf.classList.add("turning");lf.style.zIndex=300;BK.k=target;lf.classList.toggle("flipped",dir>0);setBookState();
  setTimeout(()=>{lf.classList.remove("turning");layoutBook();BK.busy=false},reduced()?60:950);
}
async function goToSpread(k){k=Math.max(0,Math.min(BK.L,k));let guard=0;while(BK.k!==k&&guard++<60){turn(BK.k<k?1:-1);await wait(reduced()?90:360)}}
$("#bookPrev").onclick=()=>turn(-1);$("#bookNext").onclick=()=>turn(1);
const shell=$("#bookShell");
shell.addEventListener("click",e=>{
  const g=e.target.closest("[data-entry]");if(g){goToSpread(spreadTarget(+g.dataset.entry));return}
  const o=e.target.closest("[data-open]");if(o){goCountry(o.dataset.open,"#guide");return}
  if(e.target.closest("[data-start]")){$(".challenge-area").scrollIntoView({behavior:"smooth"});return}
  if(e.target.closest("button,a,input"))return;
  const face=e.target.closest(".face");if(!face)return;
  if(BK.single){const r=shell.getBoundingClientRect();turn(e.clientX<r.left+r.width*.3?-1:1);return}
  if(face.classList.contains("back")&&face.parentElement.classList.contains("flipped"))turn(-1);else turn(1)});
shell.addEventListener("keydown",e=>{if(e.key==="ArrowRight"){e.preventDefault();turn(1)}else if(e.key==="ArrowLeft"){e.preventDefault();turn(-1)}else if(e.key==="Home"){e.preventDefault();goToSpread(0)}else if(e.key==="End"){e.preventDefault();goToSpread(BK.single?BK.L-1:BK.L)}});
let sx=null;shell.addEventListener("pointerdown",e=>{sx=e.clientX});shell.addEventListener("pointerup",e=>{if(sx==null)return;const dx=e.clientX-sx;sx=null;if(Math.abs(dx)>60)turn(dx<0?1:-1)});
mqBook.addEventListener&&mqBook.addEventListener("change",()=>renderBook());
/* arrow keys turn pages whenever the book is on screen (unless typing) */
let bookInView=false;
if("IntersectionObserver"in window)new IntersectionObserver(es=>es.forEach(e=>{bookInView=e.isIntersecting}),{threshold:.5}).observe(shell);
document.addEventListener("keydown",e=>{if(!bookInView||e.defaultPrevented||/INPUT|TEXTAREA|SELECT/.test(e.target.tagName))return;
  if(e.key==="ArrowRight"){turn(1)}else if(e.key==="ArrowLeft"){turn(-1)}});
