let ticking=false;
addEventListener("scroll",()=>{if(ticking)return;ticking=true;requestAnimationFrame(()=>{const h=document.documentElement,max=h.scrollHeight-innerHeight;$("#scrollProgress").style.width=(max>0?scrollY/max*100:0)+"%";$("#toTop").classList.toggle("show",scrollY>800);if(!reduced()&&scrollY<900){const hp=$(".hero-art");if(hp)hp.style.transform=`translateY(${scrollY*.08}px)`}ticking=false})},{passive:true});
$("#toTop").onclick=()=>scrollTo({top:0,behavior:"smooth"});
if("IntersectionObserver"in window){
  const io=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){e.target.classList.add("visible");io.unobserve(e.target)}}),{threshold:.1});$$(".reveal,.reveal-up").forEach(el=>io.observe(el));
  const links=$$(".main-nav a"),map={home:"#home",world:"#explore",explore:"#explore",guide:"#guide",moments:"#moments",book:"#book"};
  const so=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){links.forEach(a=>a.classList.toggle("active",a.getAttribute("href")===map[e.target.id]))}}),{rootMargin:"-40% 0px -55% 0px"});
  $$("main > section").forEach(s=>so.observe(s));
}else $$(".reveal,.reveal-up").forEach(el=>el.classList.add("visible"));
function countUp(){const el=$("#heroCount"),end=COUNTRY_LIST.length;if(reduced()){el.textContent=end;return}const t0=performance.now();(function f(n){const p=Math.min(1,(n-t0)/1400);el.textContent=Math.round(end*(1-Math.pow(1-p,3)));if(p<1)requestAnimationFrame(f)})(t0)}

/* migrate saved data from earlier versions */
function migrate(){if(store.get("discoverV",0)>=3)return;
  const book=store.get("discoverBook",[]).map(e=>({...e,code:e.code||legacyCode(e.key||e.name)})).filter(e=>e.code);
  if(localStorage.getItem("discoverBook")!==null){const seen=new Set();const ordered=[...book].sort((a,b)=>(a.ts||0)-(b.ts||0)).filter(e=>!seen.has(e.code)&&seen.add(e.code));store.set("discoverBook",ordered)}
  const tasks=store.get("discoverTasks",{}),nt={};Object.keys(tasks).forEach(k=>{const c=BY_CODE[k]?k:legacyCode(k);if(c)nt[c]=tasks[k]});if(localStorage.getItem("discoverTasks")!==null)store.set("discoverTasks",nt);
  const old=store.get("discoverPosts",null);if(Array.isArray(old)){const mine=old.filter(p=>p&&p.user==="you").map((p,i)=>({...p,id:"u"+Date.now()+i,mine:true}));if(mine.length&&!store.get("discoverMyPosts",null))store.set("discoverMyPosts",mine);try{localStorage.removeItem("discoverPosts")}catch(e){}}
  const ps=store.get("discoverPostState",null);if(ps&&!ps.comments){ps.comments={};store.set("discoverPostState",ps)}
  store.set("discoverV",3)}

/* ---------- boot ---------- */
migrate();
